import { publish, subscribe, unsubscribe } from 'pubsub-js';
import { useCallback, useMemo } from 'react';

const SURVEY_TOPIC_NAME = 'BEES_ONE_USER_SURVEY';
const PubSub = { publish, subscribe, unsubscribe };

export type SurveyCallback = (surveyId: string) => void;

export const useSurvey = (surveyId?: string) => {
  const openSurvey = useCallback(() => {
    PubSub.publish(SURVEY_TOPIC_NAME, surveyId ?? 'none');
  }, [surveyId]);

  const engine = useMemo(
    () => ({
      subscribe: (callback: SurveyCallback) =>
        PubSub.subscribe(SURVEY_TOPIC_NAME, (_: string, data: string) => callback(data)),
      unsubscribe: (subscription: string) => PubSub.unsubscribe(subscription)
    }),
    []
  );

  return {
    openSurvey,
    engine
  };
};
