import { useCountryService } from './useCountryService';

type CountryApiMap = Record<string, string>;
interface CountryApiMapStorage {
  data: CountryApiMap;
  timestamp: number;
}

const COUNTRY_API_MAP_STORAGE_KEY = 'bees-one-country-api-map';
const COUNTRY_API_MAP_STORAGE_EXPIRATION_TIME = 1000 * 60 * 60 * 24; // 24 hours

const isStorageExpired = (timestamp: number) => {
  return Date.now() - timestamp > COUNTRY_API_MAP_STORAGE_EXPIRATION_TIME;
};

export const useCountryApiMap = () => {
  const { data: countriesData } = useCountryService();
  const countryApiMap = getCountryApiStorage();

  if (!isStorageExpired(countryApiMap.timestamp) && Object.keys(countryApiMap.data).length > 0) {
    return countryApiMap.data;
  }

  const countriesList = Array.isArray(countriesData) ? countriesData : [countriesData];

  const urlMapping: CountryApiMap = {};
  countriesList.forEach(country => {
    if (country) urlMapping[country.code] = country.apiUrl;
  });
  localStorage.setItem(
    COUNTRY_API_MAP_STORAGE_KEY,
    JSON.stringify({ data: urlMapping, timestamp: Date.now() })
  );

  return urlMapping;
};

export const getCountryApiStorage = () => {
  const storage = localStorage.getItem(COUNTRY_API_MAP_STORAGE_KEY);
  return (storage ? JSON.parse(storage) : { data: {}, timestamp: 0 }) as CountryApiMapStorage;
};
